  const maxPos = Math.min(arrLen - 1, Math.floor(steps / 2));
  let dp = new Array(maxPos + 2).fill(0);
  dp[0] = 1;

  for (let step = 1; step <= steps; step++) {
    const next = new Array(maxPos + 2).fill(0);
    for (let pos = 0; pos <= maxPos; pos++) {
      let ways = dp[pos] + dp[pos + 1];
      if (pos > 0) {
        ways += dp[pos - 1];
      }
      next[pos] = ways % MOD;
    }
    dp = next;
  }
  return dp[0];
}

