function numWays(steps, arrLen) {
  const MOD = 1000000007;
  const memo = new Map();
  // count(pos, left): ways to walk from pos back to 0 using exactly left more moves.
  const count = (pos, left) => {
    if (pos < 0 || pos >= arrLen || pos > left) return 0;
    if (left === 0) return pos === 0 ? 1 : 0;
    const key = pos * 1000 + left;
    if (memo.has(key)) return memo.get(key);
    const total = (count(pos - 1, left - 1) + count(pos, left - 1) + count(pos + 1, left - 1)) % MOD;
    memo.set(key, total);
    return total;
  };
  return count(0, steps);
}

